const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z"/><path d="M7 9h10M7 13h7"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',pipeline:'<rect x="3" y="4" width="4" height="16" rx="1"/><rect x="10" y="4" width="4" height="10" rx="1"/><rect x="17" y="4" width="4" height="13" rx="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18M7 15h2M13 15h3"/>',check:'<path d="m5 12 4 4L19 6"/>',tasks:'<rect x="4" y="3" width="16" height="19" rx="2"/><path d="m8 9 2 2 5-5M8 16h8"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',chart:'<path d="M3 3v18h18M7 16l5-6 4 3 5-8"/>',book:'<path d="M12 5C7 2 3 3 3 3v16s4-1 9 2c5-3 9-2 9-2V3s-4-1-9 2Zm0 0v16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',money:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M5 12h1M18 12h1"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'};
const ic=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const people=[{name:'Lena Brooks',initials:'LB',role:'Senior producer',leads:60,placed:20,revenue:20000,chargebacks:1000,comp:8000,marketing:1800,service:1000,color:'teal'},{name:'Morgan Reed',initials:'MR',role:'Producer',leads:80,placed:12,revenue:16000,chargebacks:1200,comp:6400,marketing:2800,service:800,color:''},{name:'Alex Carter',initials:'AC',role:'Producer',leads:65,placed:14,revenue:14000,chargebacks:800,comp:5600,marketing:2200,service:700,color:'coral'},{name:'Sofia Chen',initials:'SC',role:'Senior producer',leads:45,placed:12,revenue:12000,chargebacks:400,comp:4800,marketing:1200,service:600,color:'teal'},{name:'James Wilson',initials:'JW',role:'Producer',leads:40,placed:10,revenue:10000,chargebacks:600,comp:4000,marketing:1000,service:500,color:''},{name:'Noah Davis',initials:'ND',role:'Producer',leads:30,placed:8,revenue:8000,chargebacks:200,comp:3200,marketing:1000,service:400,color:'coral'}];
const contribution=p=>p.revenue-p.comp-p.marketing-p.service;
let state={page:'dashboard',role:'owner',tour:-1,approved:false,done:[],selected:'Rachel Bennett',search:'',period:'August 2026',stages:{},practice:0};
const navs=[['dashboard','grid','Dashboard'],['conversations','chat','Conversations'],['contacts','users','Contacts'],['opportunities','pipeline','Opportunities'],['calendar','calendar','Calendars'],['actions','tasks','Action center'],['coaching','book','Producer coaching'],['profitability','chart','Profitability & ROI']];
function avatar(p){return `<span class="avatar ${p.color||''}">${p.initials}</span>`}
function header(title,sub,extra=''){return `<div class="pagehead"><div><p class="eyebrow">NORTHSTAR INSURANCE</p><h1>${title}</h1><p class="subtext">${sub}</p></div>${extra}</div>`}
function metric(label,value,foot,icon='chart',click='financial'){return `<button class="card metric" data-action="${click}"><div class="label">${label}${ic(icon)}</div><div class="number num">${value}</div><div class="foot">${foot}</div></button>`}
function chart(){return `<svg class="chart" viewBox="0 0 700 240" role="img" aria-label="Net commission revenue and operating profit from March through August 2026. August revenue 80,000 dollars and profit 20,000 dollars."><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#917cec" stop-opacity=".18"/><stop offset="1" stop-color="#917cec" stop-opacity=".01"/></linearGradient></defs>${[30,75,120,165].map((y,i)=>`<path d="M55 ${y}H675" stroke="#edf0f5" stroke-dasharray="3 4"/><text x="5" y="${y+4}">$${[90,60,30,0][i]}k</text>`).join('')}<path d="M55 92L179 82L303 92L427 60L551 70L675 45V165H55Z" fill="url(#fill)"/><path d="M55 92L179 82L303 92L427 60L551 70L675 45" fill="none" stroke="#8c76e5" stroke-width="3"/><path d="M55 146L179 144L303 150L427 137L551 143L675 135" fill="none" stroke="#49a995" stroke-width="2.5"/>${['Mar','Apr','May','Jun','Jul','Aug'].map((x,i)=>`<text x="${55+i*124}" y="200" text-anchor="middle">${x}</text>`).join('')}<circle cx="675" cy="45" r="4" fill="#8c76e5"/><circle cx="675" cy="135" r="4" fill="#49a995"/></svg>`}
function producerTable(){return `<div class="card"><div class="cardhead"><div><h2>Producer performance</h2><p>Activity and contribution after direct costs · August 2026</p></div><span class="badge">Owner view</span></div><div class="table-wrap"><table><thead><tr><th>Producer</th><th>Leads</th><th>Placed</th><th>Conversion</th><th>Contribution</th><th>Focus</th></tr></thead><tbody>${people.slice(0,4).map((p,i)=>`<tr class="rowlink"><td><button class="tablebtn namecell" data-person="${p.name}">${avatar(p)}<span><strong>${p.name}</strong><small>${p.role}</small></span></button></td><td>${p.leads}</td><td>${p.placed}</td><td>${(p.placed/p.leads*100).toFixed(1)}%</td><td class="num"><strong>${money(contribution(p))}</strong></td><td><span class="badge ${i===1?'orange':'green'}">${i===1?'Follow-through':'On track'}</span></td></tr>`).join('')}</tbody></table></div><div class="cardfooter"><span>Showing 4 of 6 producers</span><button class="textlink" data-page="profitability">View all producers →</button></div></div>`}
function dashboard(){if(state.role==='producer')return producerHome();return header('Your agency, at a glance.','A clear view of performance. A focused plan for today.',`<div class="actions"><button data-action="period">${ic('calendar')} August 2026</button><button class="primary" data-action="brief">${ic('spark')} Daily brief</button></div>`)+`<div class="kpis">${metric('Net commission revenue','$80,000','After $4,200 in chargebacks','money')}${metric('Operating profit','$20,000','25.0% operating margin','chart')}${metric('Placed policies','76','From 320 leads · 23.8% conversion','pipeline','pipeline')}${metric('Needs your attention',state.approved?'2 items':'3 items','Today · Monday, September 21','clock','actions')}</div><div class="grid"><div class="card"><div class="cardhead"><div><h2>Agency performance</h2><p>Revenue and operating profit · Last 6 months</p></div><div class="legend"><span><i style="background:#8c76e5"></i>Revenue</span><span><i style="background:#49a995"></i>Profit</span></div></div><div class="chart-wrap">${chart()}</div><div class="cardfooter"><span>Net commission revenue, after chargebacks</span><button class="textlink" data-action="financial">Explore financials →</button></div></div><div class="card brief"><div class="cardhead"><h2>${ic('spark')} Your morning brief</h2><span class="badge">AI preview</span></div><p class="brief-intro">Monday, September 21 · 8:30 AM</p><div class="brief-item"><span class="brief-icon coral">${ic('chat')}</span><div><button data-page="conversations"><h3>${state.approved?'Rachel’s follow-up is assigned':'A customer is waiting on Morgan'} →</h3></button><p>${state.approved?'The task is ready in Morgan’s workspace.':'Rachel requested a summary. No send is recorded.'}</p></div></div><div class="brief-item"><span class="brief-icon">${ic('chart')}</span><div><button data-page="profitability"><h3>Paid social needs a closer look →</h3></button><p>Lower return after direct costs. Review execution before changing spend.</p></div></div><div class="brief-item"><span class="brief-icon teal">${ic('book')}</span><div><button data-page="coaching"><h3>One coaching focus for this week →</h3></button><p>Help Morgan agree a specific next step before ending each call.</p></div></div></div></div><div class="grid">${producerTable()}<div class="card"><div class="cardhead"><div><h2>Pipeline snapshot</h2><p>Current open opportunities · Sample records</p></div>${ic('pipeline')}</div><div class="pipeline-mini">${[['New inquiry',3,100],['Appointment',3,100],['Application',2,67],['Placed',2,67]].map(([n,v,w],i)=>`<div class="pipeline-row"><div><span>${n}</span><strong>${v}</strong></div><div class="bar"><i style="width:${w}%;background:${['#aaa0eb','#8674df','#65b7a7','#399e8a'][i]}"></i></div></div>`).join('')}</div><div class="cardfooter"><span>10 sample opportunities</span><button class="textlink" data-page="opportunities">Open pipeline →</button></div></div></div><p class="footnote">Illustrative financials · Closed month: August 2026 · Operational scenario: September 21, 2026 · All names and records are fictional.</p>`}
function render(){document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="mark">A</div>Growth & Performance<span>DEMO</span></div><button class="location" data-action="workspace">${ic('users')}<span>Northstar Insurance<small>Austin, Texas · Agency workspace</small></span></button><div class="navlabel">WORKSPACE</div><nav class="nav">${navs.filter(n=>state.role==='owner'||n[0]!=='profitability').map(([p,i,n],idx)=>`${idx===5?'<div class="navlabel">AGENCY INTELLIGENCE</div>':''}<button data-page="${p}" class="${state.page===p?'active':''}">${ic(i)}${n}${p==='actions'?`<span class="count">${state.approved?'2':'3'}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>One agency. One connected view.</strong><span>Growth and producer development</span><button class="textlink" style="color:#b6aaff;display:block;margin-top:12px" data-action="about">About this demo</button></div></aside><div class="main"><header class="topbar"><button class="ghost menu-toggle" aria-label="Toggle navigation" data-action="menu">${ic('menu')}</button><div class="breadcrumb"><span>Workspace</span><span>/</span><strong>${navs.find(n=>n[0]===state.page)?.[2]||'Dashboard'}</strong></div><div class="top-right"><button class="small" data-action="tour">${ic('spark')} Guided tour</button><select class="role" id="role" aria-label="Demo role"><option value="owner" ${state.role==='owner'?'selected':''}>Agency owner view</option><option value="producer" ${state.role==='producer'?'selected':''}>Morgan · Producer</option></select><span class="avatar">${state.role==='owner'?'AC':'MR'}</span></div></header><div class="demo-strip"><span><b>Interactive concept</b> <span class="strip-extra">· Fictional agency · Sample data · Actions are simulated</span></span><button data-action="reset">Reset demo ↺</button></div><main class="content">${tourHTML()}${views[state.page]()}</main></div><button class="askbox" data-action="ask">${ic('spark')} Ask Growth & Performance</button>`;bind();}
const contacts=[['Rachel Bennett','RB','Morgan Reed','Paid social','Appointment','Sep 18 · 2:45 PM'],['Daniel Foster','DF','Lena Brooks','Referral','Application','Sep 21 · 8:12 AM'],['Olivia Martin','OM','Alex Carter','Paid search','New inquiry','Sep 21 · 8:20 AM'],['Michael Turner','MT','Morgan Reed','Paid social','New inquiry','Sep 20 · 4:30 PM'],['Emma Collins','EC','Sofia Chen','Referral','Placed','Sep 19 · 11:00 AM'],['David Kim','DK','James Wilson','Paid search','Appointment','Sep 18 · 3:00 PM'],['Sarah Parker','SP','Noah Davis','Paid search','New inquiry','Sep 21 · 8:15 AM'],['William Hayes','WH','Lena Brooks','Referral','Placed','Sep 18 · 10:20 AM'],['Ava Mitchell','AM','Alex Carter','Paid social','Application','Sep 20 · 1:40 PM'],['James Cooper','JC','Morgan Reed','Paid social','Appointment','Sep 18 · 9:30 AM']];
const visibleContacts=()=>contacts.filter(c=>state.role==='owner'||c[2]==='Morgan Reed');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const views={dashboard,conversations,contacts:contactsView,opportunities,calendar:calendarView,actions:actionsView,coaching,profitability};
function navigate(p){if(!views[p])return;if(state.role==='producer'&&p==='profitability')return;state.page=p;state.search='';closeDrawer();render();window.scrollTo({top:0,behavior:'instant'})}
function producerHome(){return header('Your day, Morgan.','Monday, September 21 · Your next steps are ready.',`<span class="badge">Personal workspace</span>`)+`<div class="kpis">${metric('Assigned leads','80','August 2026','users','contacts')}${metric('Placed policies','12','August 2026 · 15.0% conversion','pipeline','pipeline')}${metric('Open commitments',state.approved?(state.sent?'1':'2'):'0',state.approved?'Rachel Bennett · Approved plan':'No plan approved yet','tasks','actions')}${metric('Coaching focus','1','Agree a specific next step','book','coaching')}</div><div class="grid"><div class="card"><div class="cardhead"><div><h2>Your next actions</h2><p>Assigned to you · Personal records only</p></div></div>${taskRows(true)}<div class="cardfooter"><span>Every commitment has a clear next step</span><button class="textlink" data-page="actions">All tasks →</button></div></div><div class="card lesson"><span class="badge">THIS WEEK’S FOCUS</span><h2>Make the next step specific.</h2><p>Rachel asked for a Thursday call. Before ending the conversation, confirm the time, channel and who should join.</p><button class="primary" data-action="practice">${ic('book')} Open practice scenario</button></div></div><div class="card"><div class="cardhead"><h2>Your active relationships</h2><button class="textlink" data-page="contacts">Open contacts →</button></div>${contactsTable(visibleContacts())}</div><p class="footnote">Producer view demonstrates the intended information boundary. This prototype contains fictional data; production permissions require server-side enforcement.</p>`}
function profitability(){if(state.role==='producer')return producerHome();const tab=state.finTab||'agency';return header('Profitability & ROI','Know what the agency earns—and what drives the result.',`<button data-action="definitions">${ic('info')} Metric definitions</button>`)+`<div class="tabs">${[['agency','Agency financials'],['producers','Producer contribution'],['sources','Marketing return']].map(([k,v])=>`<button data-fintab="${k}" class="${k===tab?'active':''}">${v}</button>`).join('')}</div><div class="kpis">${metric('Net commission revenue','$80,000','August 2026 · After chargebacks','money')}${metric('Contribution','$34,000','After compensation and direct costs','chart')}${metric('Shared operating costs','$14,000','Staff, software and overhead','money')}${metric('Operating profit','$20,000','25.0% of net revenue','chart')}</div>${tab==='agency'?`<div class="twocol"><div class="card"><div class="cardhead"><div><h2>From revenue to operating profit</h2><p>August 1–31, 2026 · USD · Illustrative accrual basis</p></div></div><div style="padding:0 22px 20px">${[['Gross commission revenue',84200],['Chargebacks',-4200],['Net commission revenue',80000],['Producer compensation',-32000],['Marketing spend',-10000],['Direct servicing costs',-4000],['Contribution before shared overhead',34000],['Shared operating costs',-14000],['Operating profit',20000]].map(([l,v],i)=>`<div class="detailrow ${i===8?'total':''}"><span>${l}</span><strong class="num" style="color:${v<0?'#8790a1':'inherit'}">${money(v)}</strong></div>`).join('')}</div></div><div class="stack"><div class="card lesson"><span class="badge green">RECONCILED SAMPLE DATA</span><h2>See the numbers behind the number.</h2><p>Producer contribution totals $34,000. Shared costs of $14,000 bring operating profit to $20,000. Marketing spend is already included in direct costs.</p><button data-action="financial">Inspect supporting records ${ic('arrow')}</button></div><div class="card lesson"><h2>Cash is a separate measure.</h2><div style="font-size:32px;font-weight:650">$76,000</div><p>Commission cash received in August. Timing differences mean cash received and earned commission revenue are different measures.</p><span class="footnote">Premium volume is not agency revenue. No forecasts are included in these totals.</span></div></div></div>`:tab==='producers'?`<div class="card"><div class="cardhead"><div><h2>Producer contribution</h2><p>Net revenue less compensation, marketing and direct servicing · Before shared overhead</p></div><span class="badge">6 producers</span></div><div class="table-wrap"><table><thead><tr><th>Producer</th><th>Net revenue</th><th>Compensation</th><th>Marketing</th><th>Servicing</th><th>Contribution</th></tr></thead><tbody>${people.map(p=>`<tr><td><button class="tablebtn namecell" data-person="${p.name}">${avatar(p)}<span>${p.name}</span></button></td><td>${money(p.revenue)}</td><td>${money(p.comp)}</td><td>${money(p.marketing)}</td><td>${money(p.service)}</td><td><strong>${money(contribution(p))}</strong></td></tr>`).join('')}<tr><td><strong>Total</strong></td><td>$80,000</td><td>$32,000</td><td>$10,000</td><td>$4,000</td><td><strong>$34,000</strong></td></tr></tbody></table></div></div>`:`<div class="card"><div class="cardhead"><div><h2>Return by acquisition source</h2><p>August commission activity attributed to original source · Not a lifetime cohort return</p></div></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Spend</th><th>Net revenue</th><th>Compensation + service</th><th>Contribution</th><th>Return on spend*</th></tr></thead><tbody>${[['Referral',1000,32000,14400],['Paid search',3000,28000,12600],['Paid social',6000,20000,9000]].map(([n,s,r,c])=>`<tr><td><button class="tablebtn" data-source="${n}">${n} ${ic('chevron')}</button></td><td>${money(s)}</td><td>${money(r)}</td><td>${money(c)}</td><td><strong>${money(r-c-s)}</strong></td><td><span class="badge ${n==='Paid social'?'orange':'green'}">${((r-c-s)/s*100).toFixed(0)}%</span></td></tr>`).join('')}</tbody></table></div><div class="cardfooter">*Contribution divided by marketing spend. Before shared overhead. Source allocation is illustrative.</div></div><div class="ai-panel"><h3>${ic('spark')} Look at follow-through before changing the budget.</h3><p>Paid social has the lowest contribution per dollar spent in this sample. Morgan has several paid-social inquiries, including Rachel’s unresolved follow-up. This is a reason to investigate execution—not proof that follow-up caused the difference.</p><button class="primary small" data-person="Morgan Reed">Review Morgan’s performance →</button></div>`}<p class="footnote">All figures are fictional. Producer and source views both reconcile to $80,000 net revenue and $34,000 contribution.</p>`}
function contactsTable(list){return `<div class="table-wrap"><table><thead><tr><th>Contact</th><th>Assigned producer</th><th>Source</th><th>Stage</th><th>Last activity</th></tr></thead><tbody>${list.length?list.map(c=>`<tr><td><button class="tablebtn namecell" data-contact="${c[0]}"><span class="avatar">${c[1]}</span><strong>${c[0]}</strong></button></td><td>${c[2]}</td><td>${c[3]}</td><td><span class="badge ${c[4]==='Placed'?'green':''}">${state.stages[c[0]]||c[4]}</span></td><td class="muted">${c[5]}</td></tr>`).join(''):'<tr><td colspan="5">No matching contacts. Try another name or source.</td></tr>'}</tbody></table></div>`}
function contactsView(){return header(state.role==='owner'?'Contacts':'Your contacts','A shared relationship history, with a clear owner and next step.')+`<div class="toolbar"><input id="contact-search" aria-label="Search contacts" placeholder="Search name, producer or source…" value="${esc(state.search)}"><span class="statusline">${visibleContacts().length} sample contacts · September 2026</span></div><div class="card" id="contact-table">${contactsTable(visibleContacts().filter(c=>c.join(' ').toLowerCase().includes(state.search.toLowerCase())))}</div>`}
function conversations(){const list=visibleContacts().slice(0,4);if(!list.some(c=>c[0]===state.selected))state.selected=list[0][0];const c=list.find(c=>c[0]===state.selected),r=c[0]==='Rachel Bennett';return header('Conversations','Context from the conversation. Clarity on what happens next.')+`<div class="card split"><div class="listpane">${list.map(c=>`<button class="contactitem ${c[0]===state.selected?'selected':''}" data-conversation="${c[0]}"><span class="avatar">${c[1]}</span><span><strong>${c[0]}</strong><small>${c[0]==='Rachel Bennett'?'Summary requested · Follow-up due':'Review relationship history'}</small></span></button>`).join('')}</div><div class="thread"><div class="threadhead"><div class="namecell"><span class="avatar">${c[1]}</span><span><strong>${c[0]}</strong><small>${c[2]} · ${c[3]}</small></span></div><button class="small" data-contact="${c[0]}">Contact details</button></div><p class="timestamp" style="text-align:center;margin-top:22px">${r?'FRIDAY, SEPTEMBER 18 · SAMPLE CALL TRANSCRIPT':'MONDAY, SEPTEMBER 21 · SAMPLE ACTIVITY'}</p><div class="bubble"><strong>${c[0].split(' ')[0]}</strong><br>${r?'I need to speak with my partner. Please email the summary and call me Thursday afternoon.':'Thanks for following up. Can we confirm the next step and what information you need from me?'}</div><div class="bubble out"><strong>${c[2].split(' ')[0]}</strong><br>${r?'Absolutely. I’ll send the summary this afternoon and follow up Thursday.':'Of course. I’ll check the outstanding items and send you a clear next step.'}</div><span class="timestamp">${r?'02:14–02:29 of sample call · No audio recording attached':'Sample conversation · For demonstration only'}</span>${state.sent&&r?`<div class="bubble out"><span class="badge green">SIMULATED EMAIL</span><p>${esc(state.draft||defaultDraft).replace(/\n/g,'<br>')}</p></div><span class="timestamp">Demo send recorded · Sep 21, 9:05 AM · No external message sent</span>`:''}<div class="ai-panel"><h3>${ic('spark')} Conversation insight <span class="badge">Scripted example</span></h3><p><strong>Customer said:</strong> ${r?'Another decision-maker is involved. Rachel asked for a summary and a Thursday afternoon call.':'The customer wants clarity about the next step.'}</p><p><strong>Commitment:</strong> ${r?'Morgan promised a summary on Friday. '+(state.sent?'The simulated email is now recorded.':'No email send appears in the sample activity record. Verify before assuming it was missed.'):'The producer will check the outstanding items and follow up.'}</p><p><strong>Suggested next step:</strong> ${r?'Review the summary draft and confirm a specific time for Thursday.':'Assign a follow-up task and confirm the customer’s preferred time.'}</p><div class="source">Source: fictional transcript · Agency playbook: Follow-through, §2.1</div>${r?`<div class="actions" style="margin-top:17px"><button class="primary small" data-action="${state.approved?'draft':'approve'}">${ic(state.approved?'chat':'check')}${state.approved?'Review summary draft':'Approve follow-up plan'}</button><button class="small" data-action="call-review">View coaching</button></div>`:`<button class="small" data-action="contact-followup">Review next step</button>`}</div></div></div>`}
const defaultDraft='Hi Rachel,\n\nThank you for speaking with me. I understand you would like to discuss the information with your partner before we continue.\n\nHere is a recap of our agreed next steps: you would like to discuss the information with your partner, then reconnect on Thursday afternoon. We have not confirmed a specific time yet.\n\nWould Thursday, September 24 at 2:00 PM work, and would you like your partner to join?\n\nThank you,\nMorgan';
function opportunities(){let list=visibleContacts();return header('Opportunities','Every relationship has a stage, an owner and a next step.',`<span class="badge">Life & health · Sample pipeline</span>`)+`<div class="toolbar"><span class="statusline">${list.length} sample opportunities · Use a card’s stage menu to move it</span><button data-action="pipeline-info">${ic('info')} Pipeline guide</button></div><div class="kanban">${['New inquiry','Appointment','Application','Placed'].map(stage=>{const items=list.filter(c=>(state.stages[c[0]]||c[4])===stage);return `<section class="lane"><div class="lanehead"><span>${stage}</span><span class="badge">${items.length}</span></div>${items.map(c=>`<article class="opportunity"><button class="tablebtn" data-contact="${c[0]}"><h3>${c[0]}</h3></button><p>${c[3]} · ${c[2]}</p><span class="badge ${c[0]==='Rachel Bennett'?'orange':'green'}">${c[0]==='Rachel Bennett'?(state.sent?'Summary recorded':'Summary requested'):'Next step recorded'}</span><div class="bottom"><span class="avatar">${c[2].split(' ').map(n=>n[0]).join('')}</span><select aria-label="Stage for ${c[0]}" data-stage="${c[0]}">${['New inquiry','Appointment','Application','Placed'].map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select></div></article>`).join('')||'<p class="footnote">No sample opportunities in this stage.</p>'}</section>`}).join('')}</div><p class="footnote">Stage changes update this session only. Moving a card does not confirm insurance placement or trigger a workflow.</p>`}
function taskRows(personal=false){const tasks=[...(state.approved?[['summary','Review and send Rachel’s requested summary','Morgan Reed · Today, 10:00 AM · Customer requested email','draft'],['callback','Confirm Rachel’s Thursday call time','Morgan Reed · Thu, Sep 24 · Time awaiting confirmation','schedule']]:[]),...(!personal?[['review','Verify Alex’s callback activity','Alex Carter · Today, 11:00 AM · Missing activity needs verification','verify'],['coach','Review Morgan’s coaching focus','Agency owner · Today, 2:00 PM · Specific next steps','practice']]:[])];return tasks.length?tasks.map(([id,t,d,a])=>{const done=state.done.includes(id)||(id==='summary'&&state.sent);return `<div class="task ${done?'done':''}"><button class="check ${done?'checked':''}" data-task="${id}" aria-label="${id==='summary'&&done?'Review recorded':done?'Reopen':'Review completion of'} ${t}">${done?ic('check'):''}</button><div><h3>${t}</h3><p>${d}</p>${done?'<span class="badge green" style="margin-top:9px">Demo completion recorded</span>':''}</div><button class="small taskaction" data-action="${a}">${done?'Review':id==='summary'?'Review draft':'Open'} ${ic('chevron')}</button></div>`}).join(''):`<div class="lesson"><h3>No approved follow-up plan yet</h3><p>Open Rachel’s conversation to review the suggested plan. Once approved, the summary and callback tasks appear here.</p><button class="primary" data-page="conversations">Review Rachel’s conversation →</button></div>`}
function actionsView(){return header(state.role==='owner'?'Action center':'Your action center','From a conversation to an owned, verifiable next step.',`<span class="badge">Session-only simulation</span>`)+`${!state.approved?`<div class="ai-panel" style="margin-top:0"><h3>${ic('spark')} A follow-up plan is ready for review</h3><p>Rachel Bennett requested an emailed summary and a Thursday call. Review the source conversation before assigning the plan to Morgan.</p><button class="primary small" data-page="conversations">Review conversation →</button></div>`:''}<div class="card"><div class="cardhead"><div><h2>${state.role==='owner'?'Team commitments':'Your commitments'}</h2><p>Tasks stay open until their completion is recorded.</p></div></div>${taskRows(state.role==='producer')}</div><div class="card" style="margin-top:22px"><div class="cardhead"><h2>Activity trail</h2></div><div style="padding:0 22px 22px"><div class="detailrow"><span>Sample conversation reviewed</span><span class="muted">Sep 21 · 8:30 AM</span></div>${state.approved?'<div class="detailrow"><span>Follow-up plan approved · Assigned to Morgan</span><span class="badge green">Demo approval</span></div>':''}${state.sent?'<div class="detailrow"><span>Summary email simulation completed</span><span class="badge green">Demo evidence</span></div>':''}${state.scheduled?'<div class="detailrow"><span>Thursday 2:00 PM proposed · Customer confirmation pending</span><span class="badge">Demo activity</span></div>':''}</div></div>`}
function coaching(){return header(state.role==='owner'?'Producer coaching':'Your coaching','Specific feedback, grounded in the conversation.',`<span class="badge">Agency-approved playbook · Sample</span>`)+`<div class="grid"><div class="card lesson"><span class="lesson-num">MORGAN REED · WEEKLY FOCUS</span><h1 style="font-size:26px;line-height:1.25">Turn “Thursday afternoon”<br>into a clear commitment.</h1><p>In Rachel’s call, Morgan agreed to follow up but left the time open. A small change makes the next step easier for both people.</p><div class="inset" style="margin:0"><strong>Try this:</strong><br>“Would 2:00 PM on Thursday work, and would you like your partner to join us?”</div><div class="actions"><button class="primary" data-action="practice">${ic('book')} Practise this situation</button><button data-page="conversations">See conversation</button></div></div><div class="card lesson"><span class="badge">EVIDENCE, THEN COACHING</span><h2>What supports the recommendation?</h2><p><strong>Customer statement:</strong><br>“Please email the summary and call me Thursday afternoon.”</p><p><strong>Observed gap:</strong><br>No specific time was agreed in the sample transcript.</p><p><strong>Coaching standard:</strong><br>Confirm the action, owner, date, time and channel.</p><span class="footnote">Fictional call, Sep 18 · 02:14–02:29<br>Sample playbook: Follow-through, §2.1</span></div></div><div class="twocol"><div class="card lesson"><span class="lesson-num">01 / LEARN</span><h2>A clear next step</h2><p>Use the customer’s own request to agree a useful, specific follow-up.</p><button data-action="lesson">Read the 2-minute lesson →</button></div><div class="card lesson"><span class="lesson-num">02 / REVIEW</span><h2>Check the next conversation</h2><p>A manager reviews a later call to see whether the behavior changed. Completing an exercise alone does not prove improvement.</p><button data-action="coach-review">Open manager review →</button></div></div>`}
function calendarView(){return header('Calendars','A focused week of customer conversations and team support.',`<span class="badge">September 21–25, 2026</span>`)+`<div class="card table-wrap"><div class="calendar">${['Monday','Tuesday','Wednesday','Thursday','Friday'].map((d,i)=>`<div class="day"><div class="dayhead">${d}<strong>${21+i}</strong></div>${i===0?'<div class="appointment"><span>10:00 AM · Morgan</span><strong>Rachel · Summary review</strong>Internal task</div><div class="appointment teal"><span>2:00 PM · Morgan</span><strong>Coaching check-in</strong>15 minutes</div>':i===3?`<div class="appointment"><span>${state.scheduled?'2:00 PM proposed':'Afternoon · Time to confirm'}</span><strong>Rachel Bennett</strong>Follow-up · Morgan<button class="small wide" style="margin-top:9px" data-action="schedule">${state.scheduled?'View proposal':'Propose a time'}</button></div>`:state.role==='owner'&&i===1?'<div class="appointment teal"><span>11:00 AM · Lena</span><strong>Daniel Foster</strong>Application check-in</div>':state.role==='owner'&&i===2?'<div class="appointment"><span>3:00 PM · Alex</span><strong>Ava Mitchell</strong>Requirements review</div>':'<p class="footnote" style="text-align:center">No sample events</p>'}</div>`).join('')}</div></div><p class="footnote">Illustrative agency calendar · Central Time · Proposed appointments require customer confirmation. No calendar is connected.</p>`}
const tourSteps=[['dashboard','Start with the owner’s view','See revenue, profit and the work that needs attention. Every number can be inspected.'],['profitability','Follow the money','Open Marketing return, then Paid social. Investigate the result before changing the budget.'],['conversations','Understand what was said','Review Rachel’s request and approve the follow-up plan to create Morgan’s tasks.'],['actions','Turn insight into action','Review the draft and simulate the email. The action trail records what happened.'],['dashboard','See it as the producer','Morgan sees personal tasks and coaching. Agency financials stay out of this view.']];
function tourHTML(){if(state.tour<0)return '';const s=tourSteps[state.tour];return `<div class="tour"><span class="tour-count">${state.tour+1} / 5</span><div><strong>${s[1]}</strong><p>${s[2]}</p></div><div class="actions"><button class="ghost small" data-action="exit-tour">Exit</button>${state.tour>0?'<button class="small" data-action="tour-back">Back</button>':''}<button class="primary small" data-action="tour-next">${state.tour===4?'Finish tour':'Next'} ${ic('arrow')}</button></div></div>`}
let returnFocus;
function drawer(title,html,label='AGENCY OS'){returnFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><div class="drawerhead"><div><p class="eyebrow">${label}</p><h2>${title}</h2></div><button class="ghost small" data-action="close" aria-label="Close panel">${ic('close')}</button></div>${html}</section></div>`;document.body.style.overflow='hidden';bindOverlay();document.querySelector('.drawer').focus()}
function closeDrawer(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus()}
function financialDrawer(){if(state.role!=='owner')return;drawer('A number you can inspect',`<p class="subtext">August 2026 · Fictional supporting ledger</p><div class="inset">Agency operating profit<br><strong style="font-size:32px">$20,000</strong><br>Net commission revenue minus direct costs and shared operating costs.</div>${[['Commission statement · COMM-0826',84200],['Chargeback register · CB-0826',-4200],['Compensation ledger · PAY-0826',-32000],['Marketing ledger · MKT-0826',-10000],['Servicing allocation · SVC-0826',-4000],['Shared expense ledger · OPEX-0826',-14000]].map(([n,v])=>`<div class="detailrow"><span>${n}</span><strong>${money(v)}</strong></div>`).join('')}<p class="footnote">These are sample ledger summaries, not connected records. Cash received ($76,000) is tracked separately. All financial data in this prototype is fictional.</p><button class="primary wide" style="margin-top:22px" data-page="profitability">Open full financial view</button>`,'FINANCIAL TRACEABILITY')}
function personDrawer(name){if(state.role!=='owner')return;const p=people.find(x=>x.name===name);if(!p)return;drawer(p.name,`<div class="namecell">${avatar(p)}<span><strong>${p.role}</strong><small>August 2026 · Owner-authorized view</small></span></div><div class="inset"><span>Contribution before shared overhead</span><br><strong style="font-size:30px">${money(contribution(p))}</strong></div>${[['Leads',p.leads],['Placed policies',p.placed],['Lead-to-placement conversion',(100*p.placed/p.leads).toFixed(1)+'%'],['Net commission revenue',money(p.revenue)],['Compensation',money(p.comp)],['Marketing allocation',money(p.marketing)],['Direct servicing',money(p.service)]].map(([k,v])=>`<div class="detailrow"><span>${k}</span><strong>${v}</strong></div>`).join('')}<div class="ai-panel"><h3>${ic('spark')} ${p.name==='Morgan Reed'?'A useful place to investigate':'Keep the conversation in view'}</h3><p>${p.name==='Morgan Reed'?'Morgan converted 12 of 80 leads. Rachel’s requested follow-up remains a useful case to review. This individual example does not explain the entire conversion result.':'Review the producer’s activity alongside the financial results before drawing conclusions.'}</p><button class="primary small" data-action="morgan-conversation">${p.name==='Morgan Reed'?'Review Rachel’s conversation':'Explore a sample conversation'} →</button></div>`,'PRODUCER PERFORMANCE')}
function sourceDrawer(source){if(state.role!=='owner')return;const row={'Referral':[1000,32000,14400],'Paid search':[3000,28000,12600],'Paid social':[6000,20000,9000]}[source];drawer(source,`<p class="subtext">August 2026 · Original-source attribution</p>${[['Marketing spend',row[0]],['Attributed net commission revenue',row[1]],['Attributed compensation + servicing',row[2]],['Contribution after direct costs',row[1]-row[0]-row[2]]].map(([k,v])=>`<div class="detailrow"><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}<div class="inset"><strong>How this is calculated</strong><br>Contribution ÷ marketing spend = ${((row[1]-row[0]-row[2])/row[0]*100).toFixed(0)}% return before shared overhead.<br><br>Revenue is attributed to the original lead source. This monthly activity view is not a completed acquisition cohort or lifetime return.</div><button class="primary wide" data-person="Morgan Reed">Review a producer →</button>`,'MARKETING RETURN')}
function contactDrawer(name){const c=visibleContacts().find(x=>x[0]===name);if(!c)return;drawer(name,`<div class="namecell"><span class="avatar">${c[1]}</span><span><strong>${c[2]}</strong><small>Assigned producer</small></span></div>${[['Email',c[0].toLowerCase().replace(' ','.')+'@example.com'],['Phone','(512) 555-0142'],['Original source',c[3]],['Stage',state.stages[c[0]]||c[4]],['Last activity',c[5]]].map(([k,v])=>`<div class="detailrow"><span>${k}</span><strong>${v}</strong></div>`).join('')}<div class="inset"><strong>Relationship notes</strong><br>${name==='Rachel Bennett'?'Wants to include her partner in the decision. Requested an email summary and a Thursday afternoon call. Exact time needs confirmation.':'Next step is recorded in the sample relationship history. The assigned producer owns follow-through.'}</div><div class="stack"><button class="primary" data-openconv="${c[0]}">Open conversation</button><button data-page="opportunities">View pipeline</button></div><p class="footnote">Fictional contact · Reserved example email and phone · No live messages or calls.</p>`,'CONTACT RECORD')}
function approve(){if(state.role==='individual')throw Error('Agency actions are unavailable in the individual workspace');if(!state.approved){state.approved=true;state.draft=defaultDraft;render();toast('Demo plan approved. Two tasks assigned to Morgan.')}else toast('This plan is already approved.');}
function draftDrawer(){if(!state.approved){toast('Approve the follow-up plan from the conversation first.');navigate('conversations');return;}drawer('Review Rachel’s follow-up',`<p class="subtext">To: rachel.bennett@example.com</p><div class="inset"><strong>Producer review required</strong><br>This draft recaps the agreed next steps and proposes a call time. Any product or coverage details require the licensed producer’s review before inclusion.</div><label for="draft" class="subtext" style="display:block;margin-bottom:8px">Sample email draft</label><textarea id="draft" rows="10">${esc(state.draft||defaultDraft)}</textarea><div class="actions" style="margin-top:18px"><button data-action="save-draft">Save draft</button><button class="primary" data-action="send-demo" ${state.sent?'disabled':''}>${state.sent?'Simulation recorded':'Simulate sending'}</button></div><p class="footnote">No email will be sent. This updates only the demo activity trail.</p>`,'FOLLOW-THROUGH')}
function practiceDrawer(){drawer('Practise a specific next step',`<span class="badge">Scripted practice · No live AI</span><div class="inset"><strong>Rachel says:</strong><br>“I need to speak with my partner. Please email the summary and call me Thursday afternoon.”</div><p>Which response creates the clearest next step?</p><div class="stack"><button style="text-align:left;justify-content:flex-start" data-practice="0">“Absolutely. I’ll call you sometime Thursday.”</button><button style="text-align:left;justify-content:flex-start" data-practice="1">“Would Thursday at 2:00 PM work, and would you like your partner to join?”</button><button style="text-align:left;justify-content:flex-start" data-practice="2">“I’ll add you to our follow-up list.”</button></div><div id="practice-feedback" aria-live="polite"></div><p class="footnote">Sample agency playbook · Follow-through, §2.1</p>`,'PRODUCER DEVELOPMENT')}
function askDrawer(){drawer('Ask Growth & Performance',`<span class="badge">Scripted demo answers</span><p class="subtext" style="margin:18px 0">Choose a question to see how an answer could connect to the underlying record.</p><div class="stack">${(state.role==='owner'?[['profit','What drove agency profit this month?'],['morgan','Where does Morgan need support?'],['next','What should I do next?']]:[['next','What should I do next?'],['coaching','What should I practise?'],['restricted','Can I see agency profit?']]).map(([k,v])=>`<button data-question="${k}" style="text-align:left;justify-content:flex-start">${v}</button>`).join('')}</div><div id="answer" aria-live="polite"></div><p class="footnote">Answers use a fixed fictional dataset. There is no model or live account connected.</p>`,'AGENCY INTELLIGENCE')}
function bindOverlay(){const o=document.getElementById('overlay');o.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));o.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));o.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>personDrawer(b.dataset.person));o.querySelectorAll('[data-openconv]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.openconv;navigate('conversations')});o.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{const ok=b.dataset.practice==='1';document.getElementById('practice-feedback').innerHTML=`<div class="answer"><strong>${ok?'Clear and specific.':'Make the next step more specific.'}</strong><br>${ok?'This confirms a time and includes the other decision-maker without pressuring the customer. A manager can review whether you apply this in your next call.':'Confirm the date, time, channel and who will attend. Try the response that offers a specific time and invites the partner.'}</div>`;state.practice=ok?1:0});o.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{const q=b.dataset.question;let answer;if(state.role==='producer'&&(q==='profit'||q==='restricted'||q==='morgan'))answer='Agency financials and other producers’ records are outside this role’s intended access. Your workspace shows your own activity, tasks and coaching.';else answer={profit:'August net commission revenue was $80,000. Compensation ($32,000), marketing ($10,000) and direct servicing ($4,000) left $34,000 contribution. Shared costs of $14,000 resulted in $20,000 operating profit.<br><br>Source: sample August ledger · Open Profitability & ROI to inspect the calculation.',morgan:'Morgan placed 12 of 80 leads in August. Rachel’s sample conversation shows a requested summary and an unspecified Thursday call time. Review the record and agree a precise next step; this example alone does not explain Morgan’s overall result.<br><br>Source: fictional Sep 18 transcript, 02:14–02:29.',next:state.approved?(state.sent?'Rachel’s simulated email is recorded. Confirm her Thursday call time, then review the coaching focus. Customer confirmation remains pending.':'Review Rachel’s summary draft and complete the simulated email, then propose a specific time for Thursday.'):'Review Rachel’s conversation and approve the follow-up plan. That creates two owned tasks in Morgan’s workspace.',coaching:'Practise confirming the date, time, channel and attendees for a follow-up. Start with Rachel’s Thursday-afternoon request.<br><br>Source: sample playbook, Follow-through §2.1.'}[q];document.getElementById('answer').innerHTML=`<div class="answer">${answer}</div>`});o.querySelector('.backdrop')?.addEventListener('click',e=>{if(e.target.classList.contains('backdrop'))closeDrawer()})}
function bind(){document.querySelectorAll('#app [data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('#app [data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('#app [data-person]').forEach(b=>b.onclick=()=>personDrawer(b.dataset.person));document.querySelectorAll('#app [data-source]').forEach(b=>b.onclick=()=>sourceDrawer(b.dataset.source));document.querySelectorAll('#app [data-contact]').forEach(b=>b.onclick=()=>contactDrawer(b.dataset.contact));document.querySelectorAll('[data-fintab]').forEach(b=>b.onclick=()=>{state.finTab=b.dataset.fintab;render()});document.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.conversation;render()});document.querySelectorAll('[data-stage]').forEach(b=>b.onchange=()=>{state.stages[b.dataset.stage]=b.value;render();toast('Sample opportunity moved. No workflow triggered.')});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const id=b.dataset.task;if(id==='summary'){draftDrawer();return}if(state.done.includes(id)){state.done=state.done.filter(t=>t!==id);render();return}drawer('Record demo completion',`<p>This marks the sample task complete within this demo. In the finished product, completion would need supporting activity or a reviewed record.</p><button class="primary wide" id="confirm-complete">Record simulated completion</button>`);document.getElementById('confirm-complete').onclick=()=>{state.done.push(id);closeDrawer();render();toast('Demo completion recorded.')}});document.getElementById('role').onchange=e=>{state.role=e.target.value;state.tour=-1;state.page='dashboard';closeDrawer();render()};const input=document.getElementById('contact-search');if(input)input.oninput=()=>{state.search=input.value;document.getElementById('contact-table').innerHTML=contactsTable(visibleContacts().filter(c=>c.join(' ').toLowerCase().includes(state.search.toLowerCase())));document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>contactDrawer(b.dataset.contact))}}
function toast(t){const e=document.getElementById('toast');e.className='toast';e.textContent=t;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{e.className='';e.textContent=''},4200)}
function action(a){switch(a){case 'menu':document.querySelector('.sidebar').classList.toggle('open');break;case 'close':closeDrawer();break;case 'tour':state.tour=0;state.role='owner';navigate('dashboard');break;case 'tour-next':if(state.tour===4){state.tour=-1;state.role='owner';navigate('dashboard');toast('Tour complete. Explore any part of the workspace.')}else{state.tour++;state.role=state.tour===4?'producer':'owner';navigate(tourSteps[state.tour][0])}break;case 'tour-back':state.tour--;state.role='owner';navigate(tourSteps[state.tour][0]);break;case 'exit-tour':state.tour=-1;render();break;case 'financial':financialDrawer();break;case 'pipeline':navigate('opportunities');break;case 'contacts':navigate('contacts');break;case 'actions':navigate('actions');break;case 'coaching':navigate('coaching');break;case 'approve':approve();break;case 'draft':draftDrawer();break;case 'save-draft':state.draft=document.getElementById('draft').value;toast('Draft saved in this demo session.');break;case 'send-demo':state.draft=document.getElementById('draft').value;if(!state.draft.trim()){toast('Add a message before simulating the send.');break;}state.sent=true;closeDrawer();render();toast('Email simulation recorded. No message was sent.');break;case 'practice':practiceDrawer();break;case 'ask':askDrawer();break;case 'morgan-conversation':state.selected='Rachel Bennett';navigate('conversations');break;case 'schedule':drawer('Propose a Thursday call',`<span class="badge">Rachel Bennett · Morgan Reed</span><div class="inset"><strong>Thursday, September 24 · 2:00 PM CT</strong><br>30 minutes · Include Rachel’s partner if she wishes.</div><p>This records a proposed time in the demo calendar. Customer acceptance remains pending.</p><button class="primary wide" data-action="confirm-schedule">Record proposed time</button>`,'CALENDAR COORDINATION');break;case 'confirm-schedule':state.scheduled=true;closeDrawer();render();toast('Thursday 2:00 PM proposed. Customer confirmation pending.');break;case 'brief':drawer('Your morning brief',`<p class="subtext">Monday, September 21 · 8:30 AM · Scripted example</p><div class="inset"><strong>1. Resolve Rachel’s follow-up</strong><br>${state.approved?'The plan has been assigned to Morgan.':'Review the conversation and assign a clear next step.'}</div><button class="primary wide" data-page="conversations">Review the conversation →</button><div class="inset"><strong>2. Investigate paid social return</strong><br>Review source economics and follow-through before changing the campaign budget.</div><button class="wide" data-page="profitability">Open financials →</button><div class="inset"><strong>3. Coach one specific behavior</strong><br>Help Morgan agree the exact next step before ending the call.</div><button class="wide" data-page="coaching">Open coaching →</button>`);break;case 'period':drawer('Reporting period',`<div class="inset"><strong>August 1–31, 2026</strong><br>The financial demo uses one complete month so all producer and source totals reconcile.</div><p>Operational screens show a separate scenario on September 21, 2026. The revenue chart provides six months of illustrative context.</p><button class="primary wide" data-action="close">Use August 2026</button>`);break;case 'definitions':drawer('Metric definitions',`<div class="stack">${[['Net commission revenue','Gross earned commissions less chargebacks. Premium volume and cash receipts are separate.'],['Producer contribution','Net commission revenue less producer compensation, attributed marketing and direct servicing. Before shared overhead.'],['Operating profit','Total contribution less shared operating costs. Illustrative operating measure before tax and financing.'],['Marketing return','Source contribution divided by marketing spend. Monthly original-source attribution, not cohort or lifetime ROI.'],['Conversion','Placed policies divided by assigned leads for the sample month. The sample assumes one policy per converted lead.']].map(([k,v])=>`<div><h3>${k}</h3><p class="subtext">${v}</p></div>`).join('')}</div>`);break;case 'workspace':drawer('Northstar Insurance',`<div class="inset"><strong>Fictional agency workspace</strong><br>Austin, Texas · Six producers · Life & health insurance scenario</div><p>This demo represents one agency location in a connected agency workspace. A real deployment would connect approved records from the agency and its supported financial sources.</p><p class="footnote">Only one fictional workspace exists. No agency account is connected.</p>`);break;case 'about':drawer('An experience you can explore',`<p>This is a visual concept for an insurance agency growth and producer-performance platform, with connected marketing, coaching and business-results views.</p><div class="inset"><strong>What works here</strong><br>Navigation, financial drill-downs, contact search, pipeline moves, task approvals, draft editing, simulated sending, coaching practice and role previews.</div><p><strong>What is simulated</strong><br>All records, AI answers, financial inputs and activity. No emails are sent, no live agency account is connected, and no insurance decisions are made.</p><p class="footnote">Role switching illustrates the intended interface; it is not production authentication or data security. Reloading resets the demo.</p>`);break;case 'pipeline-info':drawer('A familiar opportunity pipeline',`<p>Open a contact card to inspect the relationship, or use its stage menu to move it through the sample pipeline.</p><div class="inset">New inquiry → Appointment → Application → Placed</div><p>A stage change in the demo updates only the visible sample record. Production placement would require confirmation from an authorized source.</p>`);break;case 'verify':drawer('Verify the callback record',`<p><strong>Alex Carter · Olivia Martin</strong></p><div class="inset">A callback was expected. The sample activity feed does not show a completed call.</div><p>Missing activity is not proof that the call did not happen. The manager should verify the record with Alex before escalating.</p><button class="primary wide" data-action="verify-record">Record a simulated verification</button>`);break;case 'verify-record':if(!state.done.includes('review'))state.done.push('review');closeDrawer();render();toast('Verification recorded in demo.');break;case 'lesson':drawer('Agree the next step',`<span class="badge">Sample playbook · Follow-through §2.1</span><div class="inset">A useful commitment answers five questions: <strong>what, who, when, which channel, and who else needs to be involved?</strong></div><p>Reflect the customer’s request. Offer a specific time. Check whether another decision-maker should join. Record the agreement and give the next action an owner.</p><p>Do not treat a proposed time as confirmed, or a scheduled task as completed.</p><button class="primary wide" data-action="practice">Practise with Rachel’s example</button>`);break;case 'coach-review':drawer('Manager review',`<h3>Next-call review criteria</h3><div class="inset">Was the customer’s request understood?<br>Was a specific date and time agreed?<br>Was the right person assigned?<br>Was the commitment actually fulfilled?</div><p>No later call is available in this sample. Improvement remains unverified until a manager reviews new evidence.</p>`);break;case 'contact-followup':contactDrawer(state.selected);break;case 'reset':state={page:'dashboard',role:'owner',tour:-1,approved:false,done:[],selected:'Rachel Bennett',search:'',period:'August 2026',stages:{},practice:0};closeDrawer();render();toast('Demo reset to the starting scenario.');break;default:toast('This action is not part of the concept walkthrough.')}}
document.addEventListener('keydown',e=>{const dialog=document.querySelector('.drawer');if(!dialog)return;if(e.key==='Escape'){closeDrawer();return;}if(e.key==='Tab'){const items=[...dialog.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')];const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const registrations=[{name:'navigate_agency_demo',title:'Open agency demo view',description:'Navigate the fictional agency concept to a supported view. Changes only the current page.',inputSchema:{type:'object',properties:{page:{type:'string',enum:Object.keys(views)}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='page')||!Object.hasOwn(views,input.page))throw Error('Unsupported view');if(typeof pageAllowed==='function'&&!pageAllowed(input.page))throw Error('Unavailable in this role');navigate(input.page);return {page:state.page,role:state.role,simulated:true}}},{name:'approve_demo_followup',title:'Approve simulated follow-up',description:'Approve Rachel’s fictional follow-up plan and create two demo tasks for Morgan. Does not access live agency records or send messages.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object');approve();return {approved:state.approved,tasks:2,simulated:true}}}];for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
render();
